import { useState, useEffect } from 'react';
import axios from 'axios';

const Category = () => {
  const [categories, setCategories] = useState([]);
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/users/allcategories');
      setCategories(response.data);
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const handleAddCategory = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    formData.append("name", name);
    formData.append("image", image);

    try {
      const response = await axios.post('http://localhost:5000/api/users/addcategory', formData, {
        headers: {
          "Content-Type": "multipart/form-data"
        }
      });

      console.log("Category added:", response.data);
      setName('');
      setImage(null);
      fetchCategories();
    } catch (error) {
      console.error("Error adding category:", error);
    }
  };

  return (
    <div style={{ padding: "40px",
     fontFamily: "Arial, sans-serif",
     display: "flex",
      flexDirection: "column",
       alignItems: "center" }}>


      <h2 style={{ fontSize: "50px", marginBottom: "20px", color: "#333" }}> Categories</h2>

      {/* Add Category Form */}
      <div style={{display: "flex", justifyContent: "center", width: "100%",flexDirection: "column", alignItems: "center"}}>
      <form
        onSubmit={handleAddCategory}
        encType="multipart/form-data"
        style={{
          display: "flex",
          alignItems: "center",
          gap: "15px",
          marginBottom: "30px",
          flexWrap: "wrap"
        }}
      >
        <input
          type="text"
          placeholder="Category Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
          style={{
            padding: "10px 15px",
            borderRadius: "6px",
            border: "1px solid #ccc",
            width: "250px"
          }}
        />
        <input
          type="file"
          accept="image/*"
          onChange={(e) => setImage(e.target.files[0])}
          required
          style={{
            padding: "10px 15px",
            borderRadius: "6px",
            border: "1px solid #ccc"
          }}
        />
        <button
          type="submit"
          style={{
            padding: "10px 20px",
            backgroundColor: "#000",
            color: "#fff",
            border: "none",
            borderRadius: "6px",
            cursor: "pointer"
          }}
        >
          ➕ Add Category
        </button>
      </form>
</div>
      {/* Category Cards */}
      <div style={{ display: "flex", flexWrap: "wrap", gap: "20px" }}>
        {categories.map((cat) => (
          <div
            key={cat._id}
            style={{
              width: "220px",
              border: "1px solid #ddd",
              borderRadius: "10px",
              overflow: "hidden",
              backgroundColor: "#fff",
              boxShadow: "0 4px 12px rgba(0, 0, 0, 0.08)",
              transition: "transform 0.2s ease",
              cursor: "pointer"
            }}
            onMouseOver={(e) => {
              e.currentTarget.style.transform = "translateY(-5px)";
            }}
            onMouseOut={(e) => {
              e.currentTarget.style.transform = "translateY(0)";
            }}
          >
            <img
              src={`http://localhost:5000/uploads/${cat.image}`}
              alt={cat.name}
              style={{ width: "100%", height: "140px", objectFit: "cover" }}
            />
            <div style={{ padding: "12px", textAlign: "center" }}>
              <h4 style={{ margin: "0", fontSize: "18px", color: "#333" }}>{cat.name}</h4>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Category;
